(2, 'Heart Cop in United Hospital', '43', 'public/uploads/national_work/images/Screenshot_23.png', 'Heart Cop in United', 'fa fa-medkit', '<p><span style=\"color: rgb(66, 66, 66);\">দেশেসেরা হসপিটাল ইউনাইটেডে চলছে ওয়েক আপ এর সফটওয়্যার _\"হার্ট কপ\"</span></p>', 1, 1, '2022-09-25 05:35:12', '2022-09-25 05:35:12'),
(3, 'Heart Cop in  Ibrahim Cardiac Hospital & Research Institute', '43', 'public/uploads/national_work/images/Screenshot_22.png', 'Heart Cop in  Ibrahim Cardiac Hospital & Research Institute', 'fa fa-medkit', '<p><font color=\"#424242\">দেশেসেরা ইব্রাহিম কার্ডিয়াক হাসপাতাল অ্যান্ড রিসার্চ ইনস্টিটিউট&nbsp;চলছে ওয়েক আপ এর সফটওয়্যার _\"হার্ট কপ\"</font></p>', 1, 1, '2022-09-25 05:34:33', '2022-09-25 05:34:33'),
(4, 'JUTE COP  IN RAJBARI JUTE MILL', '14', 'public/uploads/national_work/images/Screenshot_24.png', 'Jute Cop', 'fa fa-industry', '<p><span style=\"color: rgb(33, 37, 41); font-family: Poppins, sans-serif;\">Rajbari Jute Mill Enterprise Resource Planning (ERP) Software is one of the biggest projects of WakeUpICT.&nbsp;</span></p>', 1, 1, '2023-01-28 11:30:21', '2023-01-28 11:30:21');
